"""Demo project «Демо: участок Северный» (ТЗ 7.5). Ported from BF demo.py: the data are generated by code with
a fixed seed (no files, no network), so every installation gets the same project.

Parts are added by the stages that bring their data types: drillholes and AU/CU assays (Э3), the audit with
deliberate errors (Э5), wireframes of the ore body (Э7), outlines (Э8), the geological map and the scan of
the section Y = 8125 (Э9). A part is a function (conn, store, rng) registered in PARTS.
"""

from __future__ import annotations

import random
from collections.abc import Callable
from typing import Any

import sqlalchemy as sa

from bf_core.db import dialect
from bf_core.projects.project import Project
from bf_core.projects.store import ProjectService
from bf_core.storage.blobs import BlobStore

DEMO_NAME = "Демо: участок Северный"
DEMO_DESCRIPTION = {"deposit": "Северное (учебное)", "license": "Учебный участок", "stage": "Разведка"}
SEED = 7

Part = Callable[[sa.Connection, BlobStore, random.Random], None]
#: (name, part) in the order of creation; later stages append theirs.
PARTS: list[tuple[str, Part]] = []


def find_demo(svc: ProjectService) -> dict[str, Any] | None:
    key = dialect.name_key(DEMO_NAME)
    return next((e for e in svc.list() if dialect.name_key(e["name"]) == key), None)


def create_or_open(svc: ProjectService) -> tuple[Project, bool]:
    """The demo project; a second call opens the one already made (ТЗ 7.5). Returns (project, created)."""
    existing = find_demo(svc)
    if existing is not None:
        return svc.open(existing["uid"]), False
    project = svc.create(DEMO_NAME, DEMO_DESCRIPTION)
    rng = random.Random(SEED)
    store = BlobStore(project.folder)
    for _name, part in PARTS:
        with dialect.write_tx(project.engine) as conn:
            part(conn, store, rng)
    return project, True
